	projectId: string;
	customerCount: number;
	apiKey?: string;
}> {
	// 1. Owner user (with a login password)
	const passwordHash = await hashPassword(DEMO_PASSWORD);
	await db
		.insert(users)
		.values({
			username: DEMO_USERNAME,
			email: DEMO_EMAIL,
			passwordHash,
		})
		.onConflictDoUpdate({
			target: users.username,
			set: { passwordHash, email: DEMO_EMAIL },
		});
